import java.util.Scanner;

class Account {
    private final String owner;
    private int balance;

    Account(String owner, int initial) {
        this.owner = owner;
        this.balance = initial < 0 ? 0 : initial;
    }

    String getOwner() {
        return owner;
    }

    int getBalance() {
        return balance;
    }

    boolean deposit(int amount) {
        if (amount <= 0) {
            return false;
        }
        balance += amount;
        return true;
    }

    boolean withdraw(int amount) {
        if (amount <= 0 || amount > balance) {
            return false;
        }
        balance -= amount;
        return true;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String owner = sc.next();
        int initial = sc.nextInt();
        int k = sc.nextInt();

        Account account = new Account(owner, initial);

        for (int i = 0; i < k; i++) {
            String command = sc.next();
            int amount = sc.nextInt();

            boolean ok;
            if (command.equals("D")) {
                ok = account.deposit(amount);
            } else {
                ok = account.withdraw(amount);
            }

            System.out.println((ok ? "" : "失敗 ") + "残高 " + account.getBalance());
        }

        System.out.println(account.getOwner() + " " + account.getBalance());
    }
}
